begin;
create temporary table hd_rappel_court as select gen_random_uuid()u,gen_random_uuid()p;
insert into auth.users(id)select u from hd_rappel_court;
insert into seneve.participants(participant_id,auth_user_id,prenom,fuseau)select p,u,'RECETTE_RAPPEL_COURT','Africa/Kinshasa'from hd_rappel_court;
select set_config('request.jwt.claim.sub',(select u::text from hd_rappel_court),true);
do $$declare p uuid;eid uuid;a1 uuid;a2 uuid;r1 uuid;r2 uuid;cat jsonb;o jsonb;h jsonb;j jsonb;begin
 select x.p into p from hd_rappel_court x;
 cat:=seneve.hd_free_catalogue('fr');
 select value into o from jsonb_array_elements(cat->'offres')where value->>'offre_id'='HD_RECETTE_INSCRIPTION_FR_20261026_30J';
 select jsonb_agg(jsonb_build_object('habit_key',x->'habit_key','creneaux',x->'creneaux'))into h from jsonb_array_elements(o->'planning')x;
 perform seneve.hd_start_free(o->>'programme_id',1,'fr',o->>'offre_id',h,true);
 select e.enrollment_id into eid from seneve.enrollments e where e.participant_id=p and e.programme_id='HD_RECETTE_INSCRIPTION_FR_20261026';
 select a.activity_id into a1 from seneve.activities a join seneve.contents c using(content_id)where c.programme_id='HD_RECETTE_INSCRIPTION_FR_20261026'and c.jour=1 and a.note_source='RECETTE_HD_QUOTIDIEN_V1:priere_matin';
 select a.activity_id into a2 from seneve.activities a join seneve.contents c using(content_id)where c.programme_id='HD_RECETTE_INSCRIPTION_FR_20261026'and c.jour=1 and a.note_source='RECETTE_HD_QUOTIDIEN_V1:priere_midi';
 insert into seneve.hd_activity_reminders(enrollment_id,activity_id,canal,creneau)values(eid,a1,'push',now())returning reminder_id into r1;
 insert into seneve.hd_activity_reminders(enrollment_id,activity_id,canal,creneau)values(eid,a2,'push',now())returning reminder_id into r2;
 if(seneve.hd_reminder_precheck(r1)->>'eligible_interne')::boolean then raise exception 'Configuration absente acceptée';end if;
 insert into seneve.hd_delivery_preferences(participant_id,actif,fuseau,canaux,max_retard_minutes)values(p,true,'Africa/Kinshasa',array['push'],10);
 insert into seneve.push_appareils(participant_id,endpoint,p256dh,auth)values(p,'https://example.invalid/'||p,repeat('x',30),repeat('x',15));
 if(seneve.hd_reminder_precheck(r1)->>'eligible_interne')::boolean then raise exception 'Sans consentement accepté';end if;
 insert into seneve.consents(participant_id,canal,finalite,etat,version_texte,preuve,decide_le)values(p,'push','rappels','accorde','RECETTE','FICTIVE',now()-interval '1 minute');
 j:=seneve.hd_reminder_precheck(r1);
 if not(j->>'eligible_interne')::boolean or(j->>'autorisation_envoi')::boolean then raise exception 'Précontrôle incorrect : %',j;end if;
 update seneve.hd_delivery_preferences x set silence_debut=((now()at time zone 'Africa/Kinshasa')::time-interval '1 minute')::time,silence_fin=((now()at time zone 'Africa/Kinshasa')::time+interval '1 minute')::time where x.participant_id=p;
 if seneve.hd_reminder_precheck(r1)->>'motif'<>'heure_de_silence'then raise exception 'Silence ignoré';end if;
 update seneve.hd_delivery_preferences x set silence_debut=null,silence_fin=null where x.participant_id=p;
 insert into seneve.consents(participant_id,canal,finalite,etat,version_texte,preuve)values(p,'push','rappels','retire','RECETTE','FICTIVE');
 if(seneve.hd_reminder_precheck(r1)->>'eligible_interne')::boolean then raise exception 'Retrait ignoré';end if;
 perform seneve.record_progress(eid,a1,gen_random_uuid(),'partielle','web');
 if(select etat from seneve.hd_activity_reminders where reminder_id=r1)<>'planifie'then raise exception 'Partiel a annulé le rappel';end if;
 perform seneve.record_progress(eid,a1,gen_random_uuid(),'realisee','web');
 if(select etat from seneve.hd_activity_reminders where reminder_id=r1)<>'annule'or(select etat from seneve.hd_activity_reminders where reminder_id=r2)<>'planifie'then raise exception 'Annulation non ciblée';end if;
end$$;
select 'Configuration, accord/retrait, silence, pas d’envoi, partiel et annulation ciblée : OK. Tout annulé.'resultat;
rollback;